],"rec":null,"instId":"i4","date":"2026-11-04","time":"19:00"},{"id":"s0261","mode":"Online","course":"Digital Marketing","cap":8,"dur":null,"link":"","leadMin":null,"bookings":[{"name":"Lina Farouk","phone":"01001234567","email":"lina@example.com","university":"Cairo University","pin":"123456","kind":"single","seats":1,"cur":"EGP","at":"2026-11-02T16:54:06.594Z","subject":"Digital Marketing","topic":"Campaign brief","price":450,"pay":{"status":"unpaid"}}],"materials":[],"rec":null,"instId":"i2","date":"2026-11-05","time":"17:00"}],"requests":[{"id":"q-demo","kind":"class","name":"Omar Samir","phone":"01009876543","email":"omar@example.com","course":"Thermodynamics","instId":"i7","students":4,"times":"Saturdays after 6 PM","mode":"Online","note":"Exam in three weeks","status":"new","at":"2026-11-02T16:54:06.594Z"}]}$ubseed$::jsonb;
  el jsonb;
  b jsonb;
  slot_body jsonb;
  pin_student text := extensions.crypt('123456', extensions.gen_salt('bf'));
begin
  delete from public.ub_bookings;
  delete from public.ub_slots;
  delete from public.ub_requests;
  delete from public.ub_courses;
  delete from public.ub_categories;
  delete from public.ub_instructors;

  update public.ub_settings
  set body = coalesce(body, '{}'::jsonb) || (spec->'settings')
  where id = 'main';

  for el in select value from jsonb_array_elements(spec->'instructors')
  loop
    insert into public.ub_instructors (id, body, pin_hash)
    values (
      el->>'id',
      el - 'pin',
      extensions.crypt(el->>'pin', extensions.gen_salt('bf'))
    );
  end loop;

  for el in select value from jsonb_array_elements(spec->'catalog'->'cats')
  loop
    insert into public.ub_categories (id, body) values (el->>'id', el);
  end loop;

  for el in select value from jsonb_array_elements(spec->'catalog'->'courses')
  loop
    insert into public.ub_courses (id, body) values (el->>'id', el);
  end loop;

  for el in select value from jsonb_array_elements(spec->'slots')
  loop
    slot_body := el - 'id' - 'instId' - 'date' - 'time' - 'bookings' - 'booked' - 'hasLink';
    insert into public.ub_slots (id, inst_id, slot_date, slot_time, body)
    values (el->>'id', el->>'instId', (el->>'date')::date, left(el->>'time', 5), slot_body);
    for b in select value from jsonb_array_elements(coalesce(el->'bookings', '[]'::jsonb))
    loop
      insert into public.ub_bookings (slot_id, phone_norm, kind, seats, pin_hash, body)
      values (
        el->>'id',
        public.ub_phone(b->>'phone'),
        coalesce(b->>'kind', ''),
        coalesce((b->>'seats')::int, 1),
        pin_student,
        b - 'pin'
      );
    end loop;
  end loop;

  for el in select value from jsonb_array_elements(spec->'requests')
  loop
    insert into public.ub_requests (body) values (el - 'id');
  end loop;
end
$body$;
